#!/usr/bin/env python3
"""Generate tools/hints_player.txt: the player state dispatch table (bank 2 $B5AA, indexed by player_state; handlers in the fixed bank)."""
import os, collections
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
d = open(os.path.join(ROOT, 'rom/game.nes'), 'rb').read()
b2 = d[16 + 2 * 16384:16 + 3 * 16384]
def wd(a): return b2[a - 0x8000] | b2[a - 0x7FFF] << 8
T, N = 0xB5AA, 31
# meaning of each state ([v] = verified by driving the emulator, others read from the code)
DESCR = {0x00: 'on the ground (walk, start jump, peck)', 0x01: 'rising in a jump [v]', 0x02: 'falling [v]', 0x03: 'landing variant when zp_7C is non-zero: sfx $11, a 17-tick animation (bank 2 $B53A), camera shake after long falls, brief invulnerability; code-read, not triggered',
         0x04: 'landing recovery [v]', 0x05: 'peck: inspects the tile in front of the beak [v]', 0x06: 'peck swing (nothing solid) [v]', 0x07: 'peck hit (solid tile) [v]',
         0x08: 'spring bounce: 19 ticks at 3 px (zp_8F/zp_8B), then continues as $01; entered by landing on a spring tile (sfx $27) or jumping while touching one [v]', 0x09: 'start of life: drops in via $0E, falls, lands [v]',
         0x0A: 'returns to $00 immediately', 0x0D: 'in water (below water_level)', 0x0E: 'one-tick hand-over to falling after a spawn [v]',
         0x0F: 'hurt / death animation, about 21 ticks [v]', 0x10: 'dead: waits about 100 ticks, lives--, then respawn ($11) or game over [v]',
         0x11: 'respawn arc 1 (bank 1) [v]', 0x12: 'respawn arc 2 [v]', 0x13: 'respawn arc 3 [v]', 0x14: 'respawn arc 4 [v]', 0x15: 'respawn arc 5, ends via $0E [v]',
         0x16: 'balloon ride: carried up by the popped balloon, then moved to area 4 [v]', 0x17: 'bonus ascent through area 4 collecting points [v]',
         0x18: 'bonus tally: score added, extra life [v]', 0x19: 'walks to the NEXT sign, then the next stage starts [v]',
         0x1C: 'cutscene: walks right until X = $0140, then holds frame $44 (bank 5 $BC47; code-read, not triggered)', 0x1D: 'cutscene: stands still, frame 0 (bank 5 $BC70; code-read)', 0x1E: 'cutscene: scripted hop along a Y-offset table ($BCD7), sfx $29 and an effect burst at the end (bank 5 $BC75; code-read)',
         0x1A: 'knocked-out death animation (HurtOnTouch variant, bank 3) [v]', 0x1B: 'knocked-out death, second part, then respawn [v]'}
out = ['; generated by tools/gen_player_hints.py -- do not edit by hand',
       f'name 2 {T:X} PlayerStateHandlers', f'words 2 {T:X} {N}']
first = {}
for s in range(N): first.setdefault(wd(T + 2 * s), s)
for a, s in sorted(first.items(), key=lambda kv: kv[1]):
    also = [t for t in range(N) if wd(T + 2 * t) == a and t != s]
    out.append(f'name f {a:X} PlayerState{s:02X}   ; player_state ${s:02X}' + (f' (also {", ".join("$%02X" % t for t in also)})' if also else '') + (f' - {DESCR[s]}' if s in DESCR else ''))
open(os.path.join(ROOT, 'tools/hints_player.txt'), 'w').write('\n'.join(out) + '\n')
print(len(first), 'distinct player state handlers')
